import React, { useEffect, useMemo, useState } from 'react';
import { createRoot } from 'react-dom/client';
import './styles.css';

const API = (import.meta.env.VITE_API_URL || 'http://localhost:8000').replace(/\/api$/, '');
const apiUrl = (path: string) => `${API.replace(/\/$/, '')}${API.endsWith('/api') && path.startsWith('/api/') ? path.slice(4) : path}`;
type User = { id: string; username: string; name: string; email: string; is_admin?: boolean; is_disabled?: boolean };
type Member = User;
type Group = { id: string; name: string; owner_id: string; created_at: string; members: Member[]; participants?: { id: string; name: string; user_id?: string | null; email?: string | null }[] };
type Settlement = { group_id: string; event_ids: string[]; transfers: { from_user_id: string; to_user_id: string; amount: string }[] };
type Invite = { token: string; group_id: string; expires_at: string; url: string };
type SplitMethod = 'EQUAL' | 'PERCENTAGE' | 'FIXED';
type BillInput = { category: string; description: string; amount: string; occurred_at: string; participant_ids: string[]; receipt_name?: string; receipt_file?: File; split_method: SplitMethod; allocations: Record<string, string> };
type Bill = BillInput & { id: string; shares: Record<string, string>; allocations: Record<string, string | null>; confirmed_participant_ids?: string[]; receipt_content_type?: string | null; receipt_size?: number | null };
type Event = { id: string; group_id: string; payer_id: string; title: string; status: string; created_at: string; total: string; bills: Bill[] };
type BillingRequest = { id: string; group_id: string; requester_id: string; recipient_id: string; participant_id?: string; amount: string; note: string; status: 'PENDING' | 'COMPLETED' | 'CANCELLED'; created_at: string; event_id?: string; bill_id?: string; completed_by?: string; completed_at?: string };
type RequestDraft = { recipientId: string; amount: string; note: string; eventId?: string; billId?: string };
type RecipientMessage = { recipient_id: string; recipient_name: string; total: string; text: string };

const categories = ['外賣', '買餸', '娛樂', '購物', '交通', '飲食', '旅遊', '住宿', '其他'];
async function api<T>(path: string, options: RequestInit = {}): Promise<T> {
  const res = await fetch(apiUrl(path), { ...options, credentials: 'include', headers: { 'Content-Type': 'application/json', ...(options.headers || {}) } });
  if (!res.ok) {
    const body = await res.json().catch(() => ({}));
  const detail = body.detail;
    const message = detail === 'Not Found' ? '找不到本機 API 服務，請重新整理頁面並確認後端已啟動。' : typeof detail === 'string' ? detail : Array.isArray(detail) ? detail.map(item => item?.msg || JSON.stringify(item)).join('；') : detail ? JSON.stringify(detail) : '出了點問題，請再試一次';
    throw new Error(message);
  }
  return res.status === 204 ? (undefined as T) : res.json();
}
async function uploadReceipt<T>(path: string, file: File): Promise<T> {
  const form = new FormData(); form.append('file', file);
  const res = await fetch(apiUrl(path), { method: 'POST', body: form, credentials: 'include' });
  if (!res.ok) { const body = await res.json().catch(() => ({})); const detail = body.detail; throw new Error(typeof detail === 'string' ? detail : '收據上載失敗'); }
  return res.json();
}
const money = (value: string | number) => `HK$${Number(value).toLocaleString('zh-HK', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}`;
const todayDate = () => new Date().toISOString().slice(0, 10);
const printRecipients = (recipientId: string) => { const selected = document.querySelector<HTMLElement>(`.recipient-card[data-recipient-id="${recipientId}"]`); if (!selected) return; const printWindow = window.open('', '_blank'); if (!printWindow) { document.body.dataset.printRequested = 'true'; document.querySelectorAll('.recipient-card').forEach(card => card.classList.toggle('print-selected', (card as HTMLElement).dataset.recipientId === recipientId)); window.setTimeout(() => window.print(), 80); return; } const styles = Array.from(document.querySelectorAll('link[rel="stylesheet"],style')).map(node => node.outerHTML).join(''); printWindow.document.write(`<!doctype html><html><head><meta charset="UTF-8"><title>分好啦｜付款單</title>${styles}</head><body data-print-requested="true"><main class="recipient-messages"><article class="recipient-card print-selected" data-recipient-id="${recipientId}">${selected.innerHTML}</article></main></body></html>`); printWindow.document.close(); printWindow.focus(); window.setTimeout(() => { printWindow.print(); printWindow.close(); }, 250); };
const isContact = (member: Member) => member.email.endsWith('@contact.local') || member.email.endsWith('@contacts.example.com');

function Auth({ onLogin }: { onLogin: (u: User) => void }) {
  const [register, setRegister] = useState(false); const [name, setName] = useState(''); const [username, setUsername] = useState(''); const [email, setEmail] = useState(''); const [password, setPassword] = useState(''); const [error, setError] = useState(''); const [busy, setBusy] = useState(false);
  async function submit(e: React.FormEvent) { e.preventDefault(); setError(''); const firstInvalid = !username.trim() ? 'username' : register && !name.trim() ? 'name' : register && !email.trim() ? 'email' : register && !/^\S+@\S+\.\S+$/.test(email) ? 'email' : !password ? 'password' : password.length < 8 ? 'password' : ''; if (firstInvalid) { setError(firstInvalid === 'username' ? '請輸入帳戶名稱。' : firstInvalid === 'name' ? '請輸入你的名字。' : firstInvalid === 'email' ? '請輸入有效的電郵地址。' : '密碼至少需要 8 個字元。'); requestAnimationFrame(() => document.querySelector<HTMLInputElement>(`[data-auth-field="${firstInvalid}"]`)?.focus()); return; } setBusy(true); try { const user = await api<User>(register ? '/api/auth/register' : '/api/auth/login', { method: 'POST', body: JSON.stringify(register ? { username, name, email, password } : { username, password }) }); localStorage.setItem('expense-splitter-session', '1'); onLogin(user); } catch (err) { setError((err as Error).message); } finally { setBusy(false); } }
  return <main className="auth-shell"><div className="auth-aside"><span className="eyebrow">分好啦 · FEN HOU LA</span><h1>一起食飯，<br/><em>唔使計到頭痕。</em></h1><p>記低你付出的每一筆，分好啦會幫大家把數目分清楚。</p><div className="receipt-art"><span>FRI 19:30</span><strong>晚餐</strong><b>HK$280.00</b><small>THANK YOU FOR SHARING</small></div></div><form className="auth-card" noValidate onSubmit={submit}><span className="eyebrow">{register ? '建立帳戶' : '歡迎回來'}</span><h2>{register ? '開一個新帳戶' : '登入分好啦'}</h2><p className="muted">{register ? '幾秒鐘就可以開始記帳。' : '使用帳戶名稱登入。'}</p><label>帳戶名稱<input data-auth-field="username" value={username} onChange={e => { setUsername(e.target.value); setError(''); }} placeholder="例如：mario_123" /></label>{register && <><label>你的名字<input data-auth-field="name" value={name} onChange={e => { setName(e.target.value); setError(''); }} placeholder="例如：Mario" /></label><label>電郵（用於聯絡）<input data-auth-field="email" type="email" value={email} onChange={e => { setEmail(e.target.value); setError(''); }} placeholder="you@example.com" /></label></>}<label>密碼<input data-auth-field="password" type="password" value={password} onChange={e => { setPassword(e.target.value); setError(''); }} placeholder="最少 8 個字元" /></label>{error && <div className="error" role="alert">{error}</div>}<button className="primary full" disabled={busy}>{busy ? '處理中…' : register ? '建立帳戶' : '登入'}</button><button type="button" className="text-button" onClick={() => { setRegister(!register); setError(''); }}>{register ? '已有帳戶？登入' : '第一次使用？建立帳戶'}</button></form></main>;
}

function Dashboard({ user, onLogout }: { user: User; onLogout: () => void }) {
  const [groups, setGroups] = useState<Group[]>([]); const [selected, setSelected] = useState<Group | null>(null); const [events, setEvents] = useState<Event[]>([]); const [requests, setRequests] = useState<BillingRequest[]>([]); const [showGroup, setShowGroup] = useState(false); const [showExpense, setShowExpense] = useState(false); const [showPeople, setShowPeople] = useState(false); const [showRequest, setShowRequest] = useState(false); const [showSettlement, setShowSettlement] = useState(false); const [showAccount, setShowAccount] = useState(false); const [requestDraft, setRequestDraft] = useState<RequestDraft | undefined>(); const [detail, setDetail] = useState<Event | null>(null); const [error, setError] = useState(''); const [notice, setNotice] = useState(''); const [confirm, setConfirm] = useState<{ message: string; action: () => Promise<void> } | null>(null);
  const isOwner = selected?.owner_id === user.id;
  useEffect(() => { if (!confirm) return; const overlay = document.createElement('div'); overlay.className = 'overlay'; const card = document.createElement('div'); card.className = 'dialog confirm-card'; const title = document.createElement('h2'); title.textContent = '請確認操作'; const copy = document.createElement('p'); copy.className = 'muted'; copy.textContent = confirm.message; const actions = document.createElement('div'); actions.className = 'details-actions'; const cancel = document.createElement('button'); cancel.className = 'secondary full'; cancel.textContent = '取消'; cancel.onclick = () => setConfirm(null); const proceed = document.createElement('button'); proceed.className = 'danger-button full'; proceed.textContent = '確定'; proceed.onclick = runConfirmation; actions.append(cancel, proceed); card.append(title, copy, actions); overlay.append(card); document.body.append(overlay); return () => overlay.remove(); }, [confirm]);
  useEffect(() => { if (!notice) return; const toast = document.createElement('div'); toast.className = 'toast'; toast.textContent = notice; document.body.append(toast); const timer = window.setTimeout(() => { toast.remove(); setNotice(''); }, 3200); return () => { window.clearTimeout(timer); toast.remove(); }; }, [notice]);
  async function loadGroups() { try { const gs = await api<Group[]>('/api/groups'); setGroups(gs); if (!selected && gs[0]) setSelected(gs[0]); } catch (e) { setError((e as Error).message); } }
  async function loadGroupData(group: Group) { try { const es = await api<Event[]>(`/api/groups/${group.id}/expenses`); const rs = group.owner_id === user.id ? await api<BillingRequest[]>(`/api/groups/${group.id}/billing-requests`) : []; setEvents(es); setRequests(rs); } catch (e) { setError((e as Error).message); } }
  useEffect(() => { loadGroups(); }, []); useEffect(() => { document.body.classList.toggle('member-view', !!selected && selected.owner_id !== user.id); return () => document.body.classList.remove('member-view'); }, [selected, user.id]);
  useEffect(() => { if (selected) loadGroupData(selected); }, [selected]);
  async function createGroup(name: string) { const group = await api<Group>('/api/groups', { method: 'POST', body: JSON.stringify({ name }) }); setGroups([...groups, group]); setSelected(group); setShowGroup(false); }
  async function createPerson(name: string) { if (!selected) return; await api<Member>(`/api/groups/${selected.id}/people`, { method: 'POST', body: JSON.stringify({ name }) }); const gs = await api<Group[]>('/api/groups'); setGroups(gs); setSelected(gs.find(g => g.id === selected.id) || selected); }
  function askConfirmation(message: string, action: () => Promise<void>) { setConfirm({ message, action }); }
  async function runConfirmation() { const action = confirm?.action; setConfirm(null); if (!action) return; try { await action(); setNotice('操作已完成。'); } catch (e) { setError((e as Error).message); } }
  async function deleteParticipant(participantId: string, name: string) { if (!selected) return; askConfirmation(`確定移除「${name}」？已有歷史分帳的參與者不能移除。`, async () => { await api(`/api/groups/${selected.id}/participants/${participantId}`, { method: 'DELETE' }); const gs = await api<Group[]>('/api/groups'); setGroups(gs); setSelected(gs.find(g => g.id === selected.id) || selected); }); }
  async function createExpense(title: string, bills: BillInput[]) { if (!selected) return; const created = await api<Event>(`/api/groups/${selected.id}/expenses`, { method: 'POST', body: JSON.stringify({ title, bills: bills.map(({ receipt_file: _receiptFile, ...b }) => ({ ...b, amount: b.amount, occurred_at: new Date(`${b.occurred_at}T00:00:00`).toISOString(), allocations: Object.fromEntries(Object.entries(b.allocations).map(([key, value]) => [key, value.trim() === '' ? null : value])) })) }) }); for (let index = 0; index < bills.length; index += 1) { const file = bills[index].receipt_file; const bill = created.bills[index]; if (file && bill) await uploadReceipt(`/api/bills/${bill.id}/receipt`, file); } setShowExpense(false); await loadGroupData(selected); }
  async function createRequest(recipientId: string, amount: string, note: string, eventId?: string, billId?: string) { if (!selected) return; await api<BillingRequest>(`/api/groups/${selected.id}/billing-requests`, { method: 'POST', body: JSON.stringify({ participant_id: recipientId, amount, note, event_id: eventId, bill_id: billId }) }); setShowRequest(false); setRequestDraft(undefined); await loadGroupData(selected); }
  async function updateRequest(request: BillingRequest, status: BillingRequest['status']) { if (!selected) return; await api<BillingRequest>(`/api/groups/${selected.id}/billing-requests/${request.id}`, { method: 'PATCH', body: JSON.stringify({ status }) }); await loadGroupData(selected); }
  async function confirmShare(billId: string, participantId: string, confirmed: boolean) { if (!detail) return; await api<Bill>(`/api/bills/${billId}/shares/${participantId}?confirmed=${confirmed}`, { method: 'PATCH' }); setDetail(await api<Event>(`/api/expenses/${detail.id}`)); await loadGroupData(selected!); }
  async function deleteGroup() { if (!selected) return; askConfirmation(`確定刪除群組「${selected.name}」及所有開支？此操作不能復原。`, async () => { const id = selected.id; await api(`/api/groups/${id}`, { method: 'DELETE' }); const remaining = groups.filter(group => group.id !== id); setGroups(remaining); setSelected(remaining[0] || null); }); }
  async function deleteEvent(event: Event) { if (!selected) return; askConfirmation(`確定刪除「${event.title}」及其所有單據？此操作不能復原。`, async () => { await api(`/api/expenses/${event.id}`, { method: 'DELETE' }); setDetail(null); await loadGroupData(selected); }); }
  async function deleteBill(billId: string) { if (!detail || !selected) return; const eventId = detail.id; askConfirmation('確定刪除這張單據？此操作不能復原。', async () => { await api(`/api/bills/${billId}`, { method: 'DELETE' }); setDetail(await api<Event>(`/api/expenses/${eventId}`)); await loadGroupData(selected); }); }
  async function createInvite() { if (!selected) return; try { const invite = await api<Invite>(`/api/groups/${selected.id}/invites`, { method: 'POST' }); await navigator.clipboard.writeText(`${window.location.origin}${invite.url}`); setNotice('邀請連結已複製，有效期 7 日。'); } catch (e) { setError((e as Error).message); } }
  const openRequest = (draft?: RequestDraft) => { setRequestDraft(draft); setShowRequest(true); };
  if (showExpense && selected) return <ExpenseFlow group={selected} user={user} onCancel={() => setShowExpense(false)} onComplete={createExpense} />;
  return <div className="app-shell"><header className="topbar"><div className="brand">分好啦<span>•</span></div><div className="user-menu"><span className="avatar">{user.name.slice(0, 1)}</span><span className="user-name">{user.name}</span><button className="text-button" onClick={() => setShowAccount(true)}>帳戶</button><button className="text-button" onClick={onLogout}>登出</button></div></header><div className="dashboard"><div className="mobile-groupbar" aria-label="選擇群組"><div className="mobile-group-scroll">{groups.map(g => <button key={g.id} className={`mobile-group-item ${selected?.id === g.id ? 'active' : ''}`} onClick={() => setSelected(g)}><span className="group-dot">{g.name.slice(0, 1)}</span><span>{g.name}</span></button>)}<button className="mobile-add-group" onClick={() => setShowGroup(true)}>＋ 新增群組</button></div></div><aside className="sidebar"><span className="eyebrow">我的群組</span>{groups.map(g => <button key={g.id} className={`group-item ${selected?.id === g.id ? 'active' : ''}`} onClick={() => setSelected(g)}><span className="group-dot">{g.name.slice(0, 1)}</span>{g.name}<span className="chevron">›</span></button>)}<button className="add-group" onClick={() => setShowGroup(true)}>＋ 新增群組</button></aside><main className="content"><div className="content-heading"><div><span className="eyebrow">{selected ? '目前群組' : '開始使用'}</span><h1>{selected?.name || '建立你的第一個群組'}</h1><p className="muted">{selected ? `${selected.members.length} 位成員 · HKD` : '和家人朋友一起記錄開支。'}</p></div>{selected && <div className="heading-actions"><button className="secondary" onClick={() => setShowPeople(true)}>成員 / 朋友</button><button className="secondary" onClick={() => setShowSettlement(true)}>結算多次開支</button><button className="secondary" onClick={deleteGroup}>刪除群組</button><button className="primary" onClick={() => setShowExpense(true)}>＋ 記一筆開支</button></div>}</div>{error && <div className="error">{error}</div>}{!groups.length ? <EmptyState onCreate={() => setShowGroup(true)} /> : <><section className="balance-card"><div><span className="eyebrow light">本群組</span><h2>{events.length ? money(events.reduce((sum, e) => sum + Number(e.total), 0)) : 'HK$0.00'}</h2><p>已記錄的總開支</p></div><div className="balance-mark">↗</div></section><div className="section-heading"><div><h2>最近開支</h2><span className="muted">點擊查看每張單據和分帳</span></div><button className="secondary request-button" onClick={() => openRequest()}>＋ 分帳請求 {requests.filter(r => r.status === 'PENDING').length ? `(${requests.filter(r => r.status === 'PENDING').length})` : ''}</button></div>{events.length ? <div className="event-list">{events.map(event => <article className="event-card" key={event.id} onClick={() => setDetail(event)}><div className="event-icon">{event.bills[0]?.category.slice(0, 1) || '•'}</div><div className="event-main"><strong>{event.title}</strong><span>{new Date(event.created_at).toLocaleDateString('zh-HK')} · {event.bills.length} 張單據 · 查看詳情</span></div><strong className="event-amount">{money(event.total)}</strong></article>)}</div> : <div className="empty-inline">還未有開支，記下第一筆吧。</div>}<RequestList requests={requests} members={selected?.members || []} onUpdate={updateRequest} /></>}</main></div>{showGroup && <GroupDialog onCancel={() => setShowGroup(false)} onCreate={createGroup} />}{showPeople && selected && <PeopleDialog group={selected} onCancel={() => setShowPeople(false)} onCreate={createPerson} onInvite={createInvite} onDelete={deleteParticipant} />}{showRequest && selected && <RequestDialog group={selected} user={user} initial={requestDraft} onCancel={() => { setShowRequest(false); setRequestDraft(undefined); }} onCreate={createRequest} />}{showSettlement && selected && <SettlementDialog group={selected} events={events} onCancel={() => setShowSettlement(false)} />}{showAccount && <AccountDialog onCancel={() => setShowAccount(false)} onDelete={async () => { await api('/api/account', { method: 'DELETE' }); localStorage.removeItem('expense-splitter-session'); onLogout(); }} />}{detail && selected && <EventDetails event={detail} group={selected} onClose={() => setDetail(null)} onRequest={openRequest} onConfirmShare={confirmShare} onDeleteEvent={deleteEvent} onDeleteBill={deleteBill} />}<nav className="mobile-nav"><button className="active">⌂<span>總覽</span></button><button onClick={() => selected && setShowExpense(true)}>＋<span>記一筆</span></button><button onClick={() => selected && setShowPeople(true)}>◎<span>成員</span></button></nav></div>;
}

function EmptyState({ onCreate }: { onCreate: () => void }) { return <div className="empty-state"><div className="empty-doodle">＋</div><h2>先建立一個群組</h2><p>可以是「屋企人」、「日本旅行」或者你和朋友的飯局。</p><button className="primary" onClick={onCreate}>建立群組</button></div>; }
function AccountDialog({ onCancel, onDelete }: { onCancel: () => void; onDelete: () => Promise<void> }) { const [error, setError] = useState(''); const [busy, setBusy] = useState(false); const [acknowledged, setAcknowledged] = useState(false); async function remove() { setBusy(true); try { await onDelete(); } catch (e) { setError((e as Error).message); setBusy(false); } } return <div className="overlay"><div className="dialog"><button className="close" onClick={onCancel}>×</button><span className="eyebrow">帳戶安全</span><h2>管理帳戶</h2><p className="muted">如你仍擁有任何群組，或曾經為已完成的開支付款，系統會保留帳戶以保障分帳紀錄。請先處理這些群組，再嘗試刪除。</p>{error && <div className="error">{error}</div>}<label className="share-check"><input type="checkbox" checked={acknowledged} onChange={e => setAcknowledged(e.target.checked)} />我明白刪除帳戶後不能復原</label><div className="details-actions"><button className="secondary full" onClick={onCancel}>取消</button><button className="danger-button full" disabled={busy || !acknowledged} onClick={remove}>{busy ? '處理中…' : '刪除帳戶'}</button></div></div></div>; }
function SettlementDialog({ group, events, onCancel }: { group: Group; events: Event[]; onCancel: () => void }) { const [selected, setSelected] = useState(events.map(event => event.id)); const [result, setResult] = useState<Settlement | null>(null); const [message, setMessage] = useState(''); const [copied, setCopied] = useState(false); const [error, setError] = useState(''); const name = (id: string) => group.members.find(member => member.id === id)?.name || '群組成員'; async function calculate() { try { setError(''); setCopied(false); const query = `?event_ids=${selected.join(',')}`; const [next, text] = await Promise.all([api<Settlement>(`/api/groups/${group.id}/settlement${query}`), api<{ text: string }>(`/api/groups/${group.id}/settlement/message${query}`)]); setResult(next); setMessage(text.text); } catch (e) { setError((e as Error).message); } } async function copyMessage() { if (!message) return; await navigator.clipboard.writeText(message); setCopied(true); } return <div className="overlay"><div className="dialog settlement-dialog"><button className="close" onClick={onCancel}>×</button><span className="eyebrow">{group.name} · 結算</span><h2>合併幾次開支</h2><p className="muted">選擇要一起計算的已完成事件，分好啦會合併每人的應付金額。</p><div className="settlement-events">{events.map(event => <label key={event.id}><input type="checkbox" checked={selected.includes(event.id)} onChange={e => setSelected(e.target.checked ? [...selected, event.id] : selected.filter(id => id !== event.id))}/><span>{event.title}<small>{new Date(event.created_at).toLocaleDateString('zh-HK')} · {money(event.total)}</small></span></label>)}</div>{error && <div className="error">{error}</div>}<button className="primary full" disabled={!selected.length} onClick={calculate}>計算結算</button>{result && <div className="settlement-result"><div className="eyebrow">建議轉帳</div>{result.transfers.length ? result.transfers.map((transfer, index) => <div className="transfer-row" key={`${transfer.from_user_id}-${transfer.to_user_id}-${index}`}><span>{name(transfer.from_user_id)} → {name(transfer.to_user_id)}</span><strong>{money(transfer.amount)}</strong></div>) : <div className="empty-inline">已經結清，沒有需要轉帳的金額。</div>}{message && <><textarea className="message-preview" readOnly value={message} aria-label="合併結算訊息"/><button className="secondary full" onClick={copyMessage}>{copied ? '已複製 ✓' : '複製分帳訊息'}</button></>}</div>}</div></div>; }
function GroupDialog({ onCancel, onCreate }: { onCancel: () => void; onCreate: (name: string) => void }) { const [name, setName] = useState(''); const [error, setError] = useState(''); return <div className="overlay"><form className="dialog" noValidate onSubmit={e => { e.preventDefault(); if (!name.trim()) { setError('請輸入群組名稱。'); document.querySelector<HTMLInputElement>('[data-dialog-field="group-name"]')?.focus(); return; } onCreate(name.trim()); }}><button type="button" className="close" onClick={onCancel}>×</button><span className="eyebrow">新群組</span><h2>這次和誰一起？</h2><label>群組名稱<input data-dialog-field="group-name" autoFocus value={name} onChange={e => { setName(e.target.value); setError(''); }} placeholder="例如：屋企人" /></label>{error && <div className="error" role="alert">{error}</div>}<button className="primary full">建立群組</button></form></div>; }
function PeopleDialog({ group, onCancel, onCreate, onInvite, onDelete }: { group: Group; onCancel: () => void; onCreate: (name: string) => Promise<void>; onInvite: () => Promise<void>; onDelete: (id: string, name: string) => Promise<void> }) { const [name, setName] = useState(''); const [busy, setBusy] = useState(false); async function submit(e: React.FormEvent) { e.preventDefault(); if (!name.trim()) return; setBusy(true); await onCreate(name.trim()); setName(''); setBusy(false); } return <div className="overlay"><div className="dialog people-dialog"><button className="close" onClick={onCancel}>×</button><span className="eyebrow">{group.name} · 成員</span><h2>加入一起分帳的人</h2><p className="muted">朋友不需要開戶，也可以參與每張單據。標示「已註冊帳戶」的是實際登入使用者。</p><div className="people-list">{group.participants?.map(participant => <div className="person-row" key={participant.id}><span className="avatar small">{participant.name.slice(0, 1)}</span><span>{participant.name}<small>{participant.user_id ? '已註冊帳戶' : '朋友（未註冊）'}</small></span>{participant.user_id !== group.owner_id && <button className="text-button" onClick={() => onDelete(participant.id, participant.name)}>移除</button>}</div>)}</div><button className="secondary full" onClick={onInvite}>複製 7 日邀請連結</button><form onSubmit={submit} className="inline-form"><input required value={name} onChange={e => setName(e.target.value)} placeholder="例如：Alice"/><button className="primary" disabled={busy}>＋ 加入</button></form></div></div>; }
function RequestDialog({ group, user, initial, onCancel, onCreate }: { group: Group; user: User; initial?: RequestDraft; onCancel: () => void; onCreate: (recipientId: string, amount: string, note: string, eventId?: string, billId?: string) => Promise<void> }) { const ownRoleId = group.participants?.find(participant => participant.user_id === user.id)?.id || user.id; const people = group.members.filter(member => member.id !== ownRoleId); const [recipient, setRecipient] = useState(initial?.recipientId || people[0]?.id || ''); const [amount, setAmount] = useState(initial?.amount || ''); const [note, setNote] = useState(initial?.note || ''); const [error, setError] = useState(''); async function submit(e: React.FormEvent) { e.preventDefault(); if (!recipient) { setError('請先選擇收款對象。'); document.querySelector<HTMLElement>('[data-dialog-field="request-recipient"]')?.focus(); return; } if (!(Number(amount) > 0)) { setError('請輸入大於 0 的有效金額。'); document.querySelector<HTMLElement>('[data-dialog-field="request-amount"]')?.focus(); return; } if (!note.trim()) { setError('請填寫備註，方便對方確認這筆請款。'); document.querySelector<HTMLElement>('[data-dialog-field="request-note"]')?.focus(); return; } try { await onCreate(recipient, amount, note.trim(), initial?.eventId, initial?.billId); } catch (e) { setError((e as Error).message); } } return <div className="overlay"><form className="dialog" noValidate onSubmit={submit}><button type="button" className="close" onClick={onCancel}>×</button><span className="eyebrow">新分帳請求</span><h2>請對方處理一筆數目</h2><p className="muted">由開支詳情帶入金額，或建立一般請求。</p><label>向誰請求<select data-dialog-field="request-recipient" value={recipient} onChange={e => { setRecipient(e.target.value); setError(''); }}>{people.map(p => <option key={p.id} value={p.id}>{p.name}</option>)}</select></label><label>金額<div className="money-input"><span>HK$</span><input data-dialog-field="request-amount" type="text" inputMode="decimal" value={amount} onChange={e => { setDecimalInput(e.target.value, setAmount); setError(''); }} placeholder="0.00" /></div></label><label>備註<input data-dialog-field="request-note" value={note} onChange={e => { setNote(e.target.value); setError(''); }} placeholder="例如：星期五晚餐" /></label>{error && <div className="error" role="alert">{error}</div>}<button className="primary full">建立請求</button></form></div>; }
function RequestList({ requests, members, onUpdate }: { requests: BillingRequest[]; members: Member[]; onUpdate: (request: BillingRequest, status: BillingRequest['status']) => void }) { if (!requests.length) return null; const name = (id: string) => members.find(m => m.id === id)?.name || '群組成員'; return <section className="requests-section"><div className="section-heading"><div><h2>分帳請求</h2><span className="muted">可追蹤待處理的數目</span></div></div><div className="request-list">{requests.map(request => <div className="request-card" key={request.id}><div className="request-icon">↗</div><div className="event-main"><strong>{name(request.requester_id)} → {name(request.participant_id || request.recipient_id)}</strong><span>{request.note} · {request.status === 'PENDING' ? '待處理' : request.status === 'COMPLETED' ? '已完成' : '已取消'}</span></div><strong className="event-amount">{money(request.amount)}</strong>{request.status === 'PENDING' && <button className="text-button" onClick={() => onUpdate(request, 'COMPLETED')}>標記完成</button>}</div>)}</div></section>; }
function setDecimalInput(value: string, setter: (value: string) => void) { if (/^\d*(\.\d{0,2})?$/.test(value)) setter(value); }
function normalizeBillAmount(value: string, setter: (value: string) => void) { setDecimalInput(value, setter); }
async function invoiceImage(event: Event, item: RecipientMessage, payerName: string): Promise<File> { const lines = [`分好啦 · 付款單`, event.title, `收款人：${payerName}`, `付款人：${item.recipient_name}`, `應付金額：${money(item.total)}`, '', ...item.text.split('\n').filter(line => line.startsWith('- ')), '', `建立日期：${new Date(event.created_at).toLocaleDateString('zh-HK')}`]; const canvas = document.createElement('canvas'); canvas.width = 1200; canvas.height = Math.max(820, 230 + lines.length * 58); const context = canvas.getContext('2d'); if (!context) throw new Error('未能建立付款單圖片'); context.fillStyle = '#fffdf7'; context.fillRect(0, 0, canvas.width, canvas.height); context.fillStyle = '#0f3f43'; context.font = 'bold 42px sans-serif'; context.fillText(lines[0], 72, 92); context.fillStyle = '#dceee9'; context.fillRect(72, 130, 1056, 150); context.fillStyle = '#0f3f43'; context.font = 'bold 50px sans-serif'; context.fillText(lines[4], 108, 223); context.fillStyle = '#526c68'; context.font = '30px sans-serif'; let y = 350; lines.slice(1, 4).forEach(line => { context.fillText(line, 72, y); y += 52; }); context.strokeStyle = '#d7dfdc'; context.beginPath(); context.moveTo(72, y + 14); context.lineTo(1128, y + 14); context.stroke(); y += 76; context.fillStyle = '#153f42'; context.font = '30px sans-serif'; lines.slice(5).forEach(line => { context.fillText(line, 72, y); y += 52; }); const blob = await new Promise<Blob>((resolve, reject) => canvas.toBlob(value => value ? resolve(value) : reject(new Error('未能輸出付款單圖片')), 'image/png')); return new File([blob], `fen-hou-la-${event.title}-${item.recipient_name}.png`, { type: 'image/png' }); }
function EventDetails({ event, group, canManage: _canManage, onClose, onRequest, onConfirmShare, onDeleteEvent, onDeleteBill }: { event: Event; group: Group; canManage?: boolean; onClose: () => void; onRequest: (draft?: RequestDraft) => void; onConfirmShare: (billId: string, participantId: string, confirmed: boolean) => Promise<void>; onDeleteEvent: (event: Event) => Promise<void>; onDeleteBill: (billId: string) => Promise<void> }) {
  const [message, setMessage] = useState(''); const [copied, setCopied] = useState(false); const [recipientMessages, setRecipientMessages] = useState<RecipientMessage[]>([]); const [messagesOpen, setMessagesOpen] = useState(false); const [messageStatus, setMessageStatus] = useState('');
  const name = (id: string) => group.members.find(member => member.id === id)?.name || group.participants?.find(participant => participant.user_id === id)?.name || '群組成員';
  async function copyMessage() { const result = await api<{ text: string }>(`/api/expenses/${event.id}/message`); await navigator.clipboard.writeText(result.text); setMessage(result.text); setCopied(true); }
  async function loadRecipientMessages() { const result = await api<{ messages: RecipientMessage[] }>(`/api/expenses/${event.id}/messages`); setRecipientMessages(result.messages); setMessagesOpen(true); }
  async function copyRecipient(item: RecipientMessage) { await navigator.clipboard.writeText(item.text); setMessageStatus(`${item.recipient_name} 的訊息已複製`); }
  async function imageFor(item: RecipientMessage) { return invoiceImage(event, item, name(event.payer_id)); }
  async function downloadImage(item: RecipientMessage) { const file = await imageFor(item); const url = URL.createObjectURL(file); const anchor = document.createElement('a'); anchor.href = url; anchor.download = file.name; anchor.click(); URL.revokeObjectURL(url); setMessageStatus(`${item.recipient_name} 的付款單圖片已下載`); }
  async function shareImage(item: RecipientMessage) { const file = await imageFor(item); if (navigator.share && (!navigator.canShare || navigator.canShare({ files: [file] }))) { await navigator.share({ title: `${event.title}｜付款單`, text: item.text, files: [file] }); setMessageStatus(`已分享 ${item.recipient_name} 的付款單圖片`); } else { await downloadImage(item); } }
  return <div className="overlay"><div className="dialog details-dialog"><button className="close" onClick={onClose}>×</button><span className="eyebrow">已完成 · {new Date(event.created_at).toLocaleDateString('zh-HK')}</span><h2>{event.title}</h2><p className="muted">由 {name(event.payer_id)} 先付款 · {event.bills.length} 張單據</p><div className="details-total"><span>事件總額</span><strong>{money(event.total)}</strong></div><div className="detail-bills">{event.bills.map(bill => <div className="detail-bill" key={bill.id}><div><strong>{bill.description}</strong><span>{bill.category} · {new Date(bill.occurred_at).toLocaleDateString('zh-HK')}</span>{bill.receipt_name && <a className="receipt-link" href={`${API}/api/bills/${bill.id}/receipt`} target="_blank" rel="noreferrer">查看收據：{bill.receipt_name}</a>}</div><strong>{money(bill.amount)}</strong><div className="detail-shares">{bill.participant_ids.map(id => <span key={id}><label className="share-check"><input type="checkbox" checked={bill.confirmed_participant_ids?.includes(id) || false} onChange={e => onConfirmShare(bill.id, id, e.target.checked)} />{name(id)} <b>{money(bill.shares[id] || 0)}</b></label><button className="share-request" onClick={() => onRequest({ recipientId: id, amount: String(bill.shares[id] || ''), note: `${event.title} · ${bill.description}`, eventId: event.id, billId: bill.id })}>請款</button></span>)}</div><button className="danger-button" onClick={() => onDeleteBill(bill.id)}>刪除單據</button></div>)}</div>{message && <textarea className="message-preview" readOnly value={message} aria-label="可複製的分帳訊息" />}{copied && <div className="success">訊息已複製，可以貼到 WhatsApp 或訊息。</div>}<div className="details-actions"><button className="secondary" onClick={copyMessage}>{copied ? '已複製 ✓' : '複製分帳訊息'}</button><button className="secondary" onClick={loadRecipientMessages}>建立付款單</button><button className="secondary full" onClick={onClose}>關閉詳情</button><button className="danger-button full" onClick={() => onDeleteEvent(event)}>刪除整個開支</button></div>{messagesOpen && <div className="recipient-messages"><div className="recipient-heading"><strong>每位朋友的付款單</strong><span className="muted">先選收款對象，再分享圖片或下載 PNG</span></div>{recipientMessages.length ? recipientMessages.map(item => <article className="recipient-card" data-recipient-id={item.recipient_id} key={item.recipient_id}><div className="recipient-card-head"><strong>{item.recipient_name}</strong><b>{money(item.total)}</b></div><p className="recipient-print-payer">付款給：{name(event.payer_id)}</p><div className="recipient-lines">{item.text.split('\n').slice(5, -2).map(line => <span key={line}>{line}</span>)}</div><div className="recipient-actions"><button className="secondary" onClick={() => copyRecipient(item)}>複製文字</button><button className="secondary" onClick={() => shareImage(item)}>分享圖片</button><button className="secondary" onClick={() => downloadImage(item)}>下載 PNG</button></div></article>) : <div className="empty-inline">沒有需要向其他成員請款的金額。</div>}{messageStatus && <div className="success">{messageStatus}</div>}</div>}</div></div>;
}
function ExpenseFlow({ group, user, onCancel, onComplete }: { group: Group; user: User; onCancel: () => void; onComplete: (title: string, bills: BillInput[]) => Promise<void> }) {
  const ownRoleId = group.participants?.find(participant => participant.user_id === user.id)?.id || user.id;
  const blank = (): BillInput => ({ category: '飲食', description: '', amount: '', occurred_at: todayDate(), participant_ids: [ownRoleId], split_method: 'EQUAL', allocations: {} });
  const [title, setTitle] = useState(''); const [bills, setBills] = useState<BillInput[]>([blank()]); const [step, setStep] = useState(0); const [error, setError] = useState('');
  const total = useMemo(() => bills.reduce((sum, bill) => sum + Number(bill.amount || 0), 0), [bills]);
  const update = (index: number, patch: Partial<BillInput>) => { setError(''); setBills(bills.map((bill, i) => i === index ? { ...bill, ...patch } : bill)); };
  const invalidField = () => { const index = bills.findIndex(bill => !bill.description.trim() || !(Number(bill.amount) > 0) || !bill.participant_ids.length); if (index < 0) return null; const bill = bills[index]; const field = !bill.description.trim() ? 'description' : !(Number(bill.amount) > 0) ? 'amount' : 'participants'; return { index, field }; };
  const validate = () => invalidField() ? '請完成標示的欄位：描述、金額，並至少選一位參與者。' : '';
  const showValidation = () => { const issue = invalidField(); if (!issue) return false; setError('請完成標示的欄位：描述、金額，並至少選一位參與者。'); window.requestAnimationFrame(() => { const target = document.querySelector<HTMLElement>(`[data-bill-index="${issue.index}"][data-field="${issue.field}"]`); (issue.field === 'participants' ? target?.querySelector<HTMLElement>('button') : target)?.focus(); }); return true; };
  async function finish() { if (showValidation()) return; try { await onComplete(title.trim() || '未命名消費', bills); } catch (e) { setError((e as Error).message); } }
  return <div className="flow-shell"><header className="flow-header"><button className="text-button" onClick={onCancel}>← 返回</button><div className="flow-steps"><span className="current">01 填寫單據</span><i>—</i><span className={step >= 1 ? 'current' : ''}>02 分給誰</span><i>—</i><span>03 完成</span></div><span className="flow-group">{group.name}</span></header><main className="flow-main"><div className="flow-intro"><span className="eyebrow">新增開支 · {group.name}</span><h1>{step === 0 ? '今天花了什麼？' : '最後看一眼，數目就清楚。'}</h1><p className="muted">{step === 0 ? '記低每張單據，之後再分給大家。' : '每張單據會按你設定的方式分帳。'}</p></div>{step === 0 ? <><label className="event-title">這次叫什麼？<input value={title} onChange={e => { setTitle(e.target.value); setError(''); }} placeholder="例如：星期五晚餐（可不填）" /></label><div className="bill-stack">{bills.map((bill, index) => <BillEditor key={index} bill={bill} index={index} members={group.members} update={update} remove={() => setBills(bills.filter((_, itemIndex) => itemIndex !== index))} canRemove={bills.length > 1} />)}</div><button className="add-bill" onClick={() => { setError(''); setBills([...bills, blank()]); }}>＋ 再加一張單據</button><div className="flow-footer"><div><span className="eyebrow">目前總額</span><strong>{money(total)}</strong></div><button className="primary" onClick={() => { if (!showValidation()) setStep(1); }}>繼續分帳 <span>→</span></button></div></> : <Review bills={bills} members={group.members} total={total} error={error} onBack={() => { setError(''); setStep(0); }} onFinish={finish} />}{error && <div className="error flow-error" role="alert">{error}</div>}</main></div>;
}
function BillEditor({ bill, index, members, update, remove, canRemove }: { bill: BillInput; index: number; members: Member[]; update: (i: number, p: Partial<BillInput>) => void; remove: () => void; canRemove: boolean }) { const setMethod = (method: SplitMethod) => { const allocations = Object.fromEntries(bill.participant_ids.map(id => [id, bill.allocations[id] || ''])); update(index, { split_method: method, allocations }); }; const setParticipants = (ids: string[]) => { const allocations = Object.fromEntries(ids.map(id => [id, bill.allocations[id] || ''])); update(index, { participant_ids: ids, allocations }); }; return <article className="bill-editor"><div className="bill-number">{String(index + 1).padStart(2, '0')}</div><div className="bill-fields"><div className="bill-row"><label>類別<select value={bill.category} onChange={e => update(index, { category: e.target.value })}>{categories.map(c => <option key={c}>{c}</option>)}</select></label><label className="amount-field">金額 <div className="money-input"><span>HK$</span><input data-bill-index={index} data-field="amount" required inputMode="decimal" type="text" value={bill.amount} onChange={e => normalizeBillAmount(e.target.value, value => update(index, { amount: value }))} placeholder="0.00" /></div></label></div><label>簡單描述<input data-bill-index={index} data-field="description" required value={bill.description} onChange={e => update(index, { description: e.target.value })} placeholder="例如：火鍋、的士" /></label><label>日期（日/月/年）<input type="date" value={bill.occurred_at.slice(0, 10)} onChange={e => update(index, { occurred_at: e.target.value })} /></label><label>收據圖片（可選）<input type="file" accept="image/jpeg,image/png" onChange={e => update(index, { receipt_file: e.target.files?.[0] })} /><small className="muted">只接受 JPG／PNG，最多 10 MB</small></label><div className="participant-label"><span>邊個要分？</span><small>至少選一位 · 可包括未註冊朋友</small></div><div className="member-pills" data-bill-index={index} data-field="participants">{members.map(member => <button type="button" key={member.id} className={bill.participant_ids.includes(member.id) ? 'selected' : ''} onClick={() => setParticipants(bill.participant_ids.includes(member.id) ? bill.participant_ids.filter(id => id !== member.id) : [...bill.participant_ids, member.id])}><span>{member.name.slice(0, 1)}</span>{member.name}{isContact(member) ? ' · 朋友' : ''}{bill.participant_ids.includes(member.id) && ' ✓'}</button>)}</div><label>分帳方式<select value={bill.split_method} onChange={e => setMethod(e.target.value as SplitMethod)}><option value="EQUAL">平均分</option><option value="FIXED">固定金額</option></select></label>{bill.split_method === 'FIXED' && <div className="allocation-grid">{bill.participant_ids.map(id => <label key={id}>{members.find(member => member.id === id)?.name || '成員'}<div className="allocation-input"><input type="text" inputMode="decimal" value={bill.allocations[id] || ''} onChange={e => update(index, { allocations: { ...bill.allocations, [id]: e.target.value } })} placeholder="留空＝剩餘" /><span>HK$</span></div></label>)}</div>}</div>{canRemove && <button className="remove-bill" onClick={remove}>刪除</button>}</article>; }
function Review({ bills, members, total, error, onBack, onFinish }: { bills: BillInput[]; members: Member[]; total: number; error: string; onBack: () => void; onFinish: () => void }) { const previewShare = (bill: BillInput, id: string) => { const amount = Number(bill.amount || 0); if (bill.split_method === 'FIXED') { const fixed = Object.entries(bill.allocations).filter(([key, value]) => key !== id && value !== '').reduce((sum, [, value]) => sum + Number(value || 0), 0); return bill.allocations[id] === '' ? amount - fixed : Number(bill.allocations[id] || 0); } return amount / bill.participant_ids.length; }; return <><div className="review-stack">{bills.map((bill, index) => <div className="review-bill" key={index}><div className="event-icon">{bill.category.slice(0, 1)}</div><div><strong>{bill.description}</strong><span>{bill.category} · {bill.split_method === 'EQUAL' ? '平均分' : '固定金額'}</span></div><strong>{money(bill.amount)}</strong></div>)}<div className="review-total"><span>總額</span><strong>{money(total)}</strong></div></div><div className="split-preview"><span className="eyebrow">分帳預覽</span>{members.filter(member => bills.some(bill => bill.participant_ids.includes(member.id))).map(member => <div className="share-row" key={member.id}><span className="avatar small">{member.name.slice(0, 1)}</span>{member.name}<strong>{money(bills.reduce((sum, bill) => bill.participant_ids.includes(member.id) ? sum + previewShare(bill, member.id) : sum, 0))}</strong></div>)}</div>{error && <div className="error">{error}</div>}<div className="flow-footer"><button className="secondary" onClick={onBack}>← 修改單據</button><button className="primary" onClick={onFinish}>完成並記錄 ✓</button></div></>; }

function AdminWorkbench({ user, onLogout }: { user: User; onLogout: () => Promise<void> }) {
  const [summary, setSummary] = useState<{ users: number; groups: number; active_groups: number; events: number; billing_requests: number; audit_entries: number } | null>(null);
  const [users, setUsers] = useState<Array<User & { created_at: string }>>([]);
  const [groups, setGroups] = useState<Array<{ id: string; name: string; owner_name: string; created_at: string; archived_at?: string | null; event_count: number }>>([]);
  const [logs, setLogs] = useState<Array<{ id: string; action: string; target_type: string; target_id?: string; detail: string; created_at: string }>>([]);
  const [error, setError] = useState(''); const [notice, setNotice] = useState(''); const [confirmTarget, setConfirmTarget] = useState<{ type: 'user' | 'group'; id: string; label: string; disabled?: boolean } | null>(null);
  async function load() { try { setError(''); const [s, u, g, l] = await Promise.all([api<typeof summary>('/api/admin/summary'), api<typeof users>('/api/admin/users'), api<typeof groups>('/api/admin/groups'), api<typeof logs>('/api/admin/audit-logs')]); setSummary(s); setUsers(u || []); setGroups(g || []); setLogs(l || []); } catch (e) { setError((e as Error).message); } }
  useEffect(() => { load(); }, []);
  async function confirmAction() { if (!confirmTarget) return; try { if (confirmTarget.type === 'user') await api(`/api/admin/users/${confirmTarget.id}/status?disabled=${!confirmTarget.disabled}`, { method: 'PATCH' }); else await api(`/api/admin/groups/${confirmTarget.id}/archive`, { method: 'POST' }); setConfirmTarget(null); setNotice('操作已記錄到管理員稽核紀錄。'); await load(); } catch (e) { setError((e as Error).message); setConfirmTarget(null); } }
  return <div className="admin-shell"><header className="topbar"><div className="brand">分好啦<span>• 管理工作台</span></div><div className="user-menu"><span className="avatar">{user.name.slice(0, 1)}</span><span>{user.name}</span><button className="text-button" onClick={onLogout}>登出</button></div></header><main className="admin-main"><div className="content-heading"><div><span className="eyebrow">OPERATOR CONSOLE · 安全管理</span><h1>管理工作台</h1><p className="muted">只用按鈕和確認視窗管理帳戶、群組與稽核紀錄。</p></div></div>{error && <div className="error" role="alert">{error}</div>}{notice && <div className="success" role="status">{notice}</div>}<section className="admin-metrics">{[['users','使用者'],['active_groups','活躍群組'],['events','開支事件'],['billing_requests','分帳請求'],['audit_entries','稽核紀錄']].map(([key,label]) => <div className="admin-metric" key={key}><span>{label}</span><strong>{summary?.[key as keyof typeof summary] ?? '—'}</strong></div>)}</section><div className="admin-grid"><section className="admin-panel"><div className="admin-panel-heading"><div><span className="eyebrow">帳戶</span><h2>使用者</h2></div><span className="muted">停用不會刪除歷史紀錄</span></div><div className="admin-list">{users.map(item => <div className="admin-row" key={item.id}><div><strong>{item.name}</strong><span>@{item.username} · {item.email}</span></div><span className={`admin-badge ${item.is_admin ? 'admin' : ''}`}>{item.is_admin ? '管理員' : item.is_disabled ? '已停用' : '一般帳戶'}</span>{!item.is_admin && <button className="secondary" onClick={() => setConfirmTarget({ type: 'user', id: item.id, label: item.name, disabled: item.is_disabled })}>{item.is_disabled ? '重新啟用' : '停用'}</button>}</div>)}</div></section><section className="admin-panel"><div className="admin-panel-heading"><div><span className="eyebrow">資料邊界</span><h2>群組</h2></div><span className="muted">封存後不會出現在一般使用者清單</span></div><div className="admin-list">{groups.map(item => <div className="admin-row" key={item.id}><div><strong>{item.name}</strong><span>擁有人：{item.owner_name} · {item.event_count} 個事件</span></div><span className={`admin-badge ${item.archived_at ? 'archived' : ''}`}>{item.archived_at ? '已封存' : '使用中'}</span>{!item.archived_at && <button className="secondary" onClick={() => setConfirmTarget({ type: 'group', id: item.id, label: item.name })}>封存</button>}</div>)}</div></section></div><section className="admin-panel audit-panel"><div className="admin-panel-heading"><div><span className="eyebrow">不可變紀錄</span><h2>最近稽核活動</h2></div></div><div className="admin-list">{logs.length ? logs.slice(0, 12).map(item => <div className="admin-row audit-row" key={item.id}><strong>{item.action}</strong><span>{item.target_type} · {item.detail || item.target_id || '—'}</span><small>{new Date(item.created_at).toLocaleString('zh-HK')}</small></div>) : <div className="empty-inline">尚未有管理員操作。</div>}</div></section></main>{confirmTarget && <div className="overlay"><div className="dialog confirm-card"><span className="eyebrow">需要確認</span><h2>{confirmTarget.type === 'group' ? '封存群組？' : confirmTarget.disabled ? '重新啟用帳戶？' : '停用帳戶？'}</h2><p className="muted">{confirmTarget.type === 'group' ? `「${confirmTarget.label}」會從一般使用者清單移除，歷史資料保留。` : `「${confirmTarget.label}」將不能登入，歷史資料保留。`}</p><div className="details-actions"><button className="secondary full" onClick={() => setConfirmTarget(null)}>取消</button><button className="danger-button full" onClick={confirmAction}>確認操作</button></div></div></div>}</div>;
}

function App() { const [user, setUser] = useState<User | null>(null); const [checking, setChecking] = useState(true); useEffect(() => { if (localStorage.getItem('expense-splitter-session')) api<User>('/api/me').then(setUser).catch(() => localStorage.removeItem('expense-splitter-session')).finally(() => setChecking(false)); else setChecking(false); }, []); useEffect(() => { const token = new URLSearchParams(window.location.search).get('invite'); if (!user || !token) return; api(`/api/invites/${encodeURIComponent(token)}/accept`, { method: 'POST' }).then(() => { window.history.replaceState({}, '', window.location.pathname); window.location.reload(); }).catch(() => window.history.replaceState({}, '', window.location.pathname)); }, [user]); if (checking) return <div className="loading">準備中…</div>; if (!user) return <Auth onLogin={setUser} />; const onLogout = async () => { await api('/api/auth/logout', { method: 'POST' }); localStorage.removeItem('expense-splitter-session'); setUser(null); }; return user.is_admin ? <AdminWorkbench user={user} onLogout={onLogout} /> : <Dashboard user={user} onLogout={onLogout} />; }
createRoot(document.getElementById('root')!).render(<React.StrictMode><App /></React.StrictMode>);







